// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {ISpotFeed} from "./ISpotFeed.sol";
import {IForwardFeed} from "./IForwardFeed.sol";
import {IInterestRateFeed} from "./IInterestRateFeed.sol";
import {IVolFeed} from "./IVolFeed.sol";

interface IPMRM {
  enum VolShockDirection {
    None,
    Up,
    Down
  }

  struct Feeds {
    ISpotFeed spotFeed;
    ISpotFeed stableFeed;
    IForwardFeed forwardFeed;
    IInterestRateFeed interestRateFeed;
    IVolFeed volFeed;
  }

  struct Portfolio {
    uint spotPrice;
    uint perpPrice;
    uint stablePrice;
    /// cash amount or debt
    int cash;
    /// option holdings per expiry
    ExpiryHoldings[] expiries;
    int perpPosition;
    uint basePosition;
    uint baseValue;
    int totalMtM;
    // Calculated values
    int basisContingency;
    // option + base + perp; excludes fwd/oracle
    uint staticContingency;
    uint confidenceContingency;
    uint minConfidence;
    int perpValue;
  }

  struct ExpiryHoldings {
    // used as key
    uint expiry;
    uint secToExpiry;
    StrikeHolding[] options;
    // portion unaffected by spot shocks
    uint forwardFixedPortion;
    // portion affected by spot shocks
    uint forwardVariablePortion;
    // We always assume the rate is >= 0
    uint rate;
    uint minConfidence;
    uint netOptions;
    int mtm;
    int basisScenarioUpMtM;
    int basisScenarioDownMtM;
    uint volShockUp;
    uint volShockDown;
    uint staticDiscount;
  }

  struct StrikeHolding {
    /// strike price of held options
    uint strike;
    uint vol;
    int amount;
    bool isCall;
    bool seenInFilter;
  }

  struct PortfolioExpiryData {
    uint64 expiry;
    uint optionCount;
  }

  struct Scenario {
    uint spotShock; // i.e. 1.2e18 = 20% spot shock up
    VolShockDirection volShock; // i.e. [Up, Down, None]
  }

  ////////////////
  //   Events   //
  ////////////////
  event MaxExpiriesUpdated(uint maxExpiries);
  event InterestRateFeedUpdated(IInterestRateFeed interestRateFeed);
  event VolFeedUpdated(IVolFeed volFeed);
  event SpotFeedUpdated(ISpotFeed spotFeed);
  event StableFeedUpdated(ISpotFeed stableFeed);
  event ForwardFeedUpdated(IForwardFeed forwardFeed);
  event ScenariosUpdated(IPMRM.Scenario[] scenarios);

  ////////////
  // Errors //
  ////////////
  error PMRM_InvalidSpotShock();
  error PMRM_UnsupportedAsset();
  error PMRM_InsufficientMargin();
  error PMRM_InvalidScenarios();
  error PMRM_InvalidMaxExpiries();
  error PMRM_FindInArrayError();
  error PMRM_OptionExpired();
  error PMRM_TooManyExpiries();
  error PMRM_TooManyAssets();
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IPMRM} from "./IPMRM.sol";

interface IPMRMLib {
  struct VolShockParameters {
    /// @dev The max vol shock, that can be scaled down
    uint volRangeUp;
    /// @dev The max
    uint volRangeDown;
    int shortTermPower;
    int longTermPower;
    uint dteFloor;
  }

  struct MarginParameters {
    uint imFactor;
    uint rateMultScale;
    uint rateAddScale;
    uint baseStaticDiscount;
  }

  struct BasisContingencyParameters {
    uint scenarioSpotUp;
    uint scenarioSpotDown;
    uint basisContAddFactor;
    uint basisContMultFactor;
  }

  struct OtherContingencyParameters {
    /// @dev Below this threshold, we consider the stable asset de-pegged, so we add additional contingency
    uint pegLossThreshold;
    /// @dev If below the peg loss threshold, we add this contingency
    uint pegLossFactor;
    /// @dev Below this threshold, IM is affected by confidence contingency
    uint confThreshold;
    /// @dev Percentage of spot used for confidence contingency, scales with the minimum contingency seen.
    uint confMargin;
    /// @dev Contingency applied to base held in the portfolio, multiplied by spot.
    uint basePercent;
    /// @dev Contingency applied to perps held in the portfolio, multiplied by spot.
    uint perpPercent;
    /// @dev Factor for multiplying number of naked shorts (per strike) in the portfolio, multipled by spot.
    uint optionPercent;
  }

  function getMarginAndMarkToMarket(IPMRM.Portfolio memory portfolio, bool isInitial, IPMRM.Scenario[] memory scenarios)
    external
    view
    returns (int margin, int markToMarket, uint worstScenario);

  function getScenarioMtM(IPMRM.Portfolio memory portfolio, IPMRM.Scenario memory scenario)
    external
    view
    returns (int scenarioMtM);

  function addPrecomputes(IPMRM.Portfolio memory portfolio) external view returns (IPMRM.Portfolio memory);

  function getBasisContingencyScenarios() external view returns (IPMRM.Scenario[] memory);

  ////////////
  // Errors //
  ////////////

  /// @dev emitted when provided forward contingency parameters are invalid
  error PMRML_InvalidBasisContingencyParameters();
  /// @dev emitted when provided other contingency parameters are invalid
  error PMRML_InvalidOtherContingencyParameters();
  /// @dev emitted when provided static discount parameters are invalid
  error PMRML_InvalidMarginParameters();
  /// @dev emitted when provided vol shock parameters are invalid
  error PMRML_InvalidVolShockParameters();
  /// @dev emitted when invalid parameters passed into _getMarginAndMarkToMarket
  error PMRML_InvalidGetMarginState();
}

